const sessions = new Map();

function isNonEmptyString(v) {
  return typeof v === 'string' && v.length > 0;
}

export async function listTools() {
  return [
    {
      name: 'begin_session',
      description: 'Begin a new session with the given session_id.',
      inputSchema: {
        type: 'object',
        properties: {
          session_id: { type: 'string' },
        },
        required: ['session_id'],
        additionalProperties: false,
      },
    },
    {
      name: 'put_value',
      description: 'Store a value for a key within a session.',
      inputSchema: {
        type: 'object',
        properties: {
          session_id: { type: 'string' },
          key: { type: 'string' },
          value: { type: 'string' },
        },
        required: ['session_id', 'key', 'value'],
        additionalProperties: false,
      },
    },
    {
      name: 'get_value',
      description: 'Retrieve a value for a key within a session.',
      inputSchema: {
        type: 'object',
        properties: {
          session_id: { type: 'string' },
          key: { type: 'string' },
        },
        required: ['session_id', 'key'],
        additionalProperties: false,
      },
    },
  ];
}

function validate(args, allowed, required) {
  for (const k of Object.keys(args)) {
    if (!allowed.includes(k)) {
      const err = new Error(`Unknown argument: ${k}`);
      err.code = -32602;
      throw err;
    }
  }
  for (const k of required) {
    if (!(k in args)) {
      const err = new Error(`Missing argument: ${k}`);
      err.code = -32602;
      throw err;
    }
  }
}

function reject(msg) {
  const err = new Error(msg);
  err.code = -32602;
  throw err;
}

export async function callTool(name, args = {}) {
  switch (name) {
    case 'begin_session': {
      validate(args, ['session_id'], ['session_id']);
      const { session_id } = args;
      if (!isNonEmptyString(session_id)) reject('session_id must be a non-empty string');
      sessions.set(session_id, new Map());
